    case 11: /* marvell_f_iwmmxt_wldr */

      temp = marvell_f_iwmmxt_min_issue_delay [(marvell_f_iwmmxt_translate [insn_code] + chip->marvell_f_iwmmxt_automaton_state * 3) / 8];
      temp = (temp >> (8 - ((marvell_f_iwmmxt_translate [insn_code] + chip->marvell_f_iwmmxt_automaton_state * 3) % 8 + 1) * 1)) & 1;
      res = temp;
      break;

