        if (arm_check [temp] != chip->arm_automaton_state)
          return internal_min_issue_delay (insn_code, chip);
        else
          _arm_automaton_state = arm_transitions [temp];

        temp = marvell_f_iwmmxt_transitions [marvell_f_iwmmxt_translate [insn_code] + chip->marvell_f_iwmmxt_automaton_state * 3];
        if (temp >= 2)
          return internal_min_issue_delay (insn_code, chip);
        else
          chip->marvell_f_iwmmxt_automaton_state = temp;
        chip->pj4_vfp_automaton_state = _pj4_vfp_automaton_state;
        chip->pj4_automaton_state = _pj4_automaton_state;
        chip->vfp11_automaton_state = _vfp11_automaton_state;
